package com.procurement.invoice.controller;import com.procurement.common.response.*;import com.procurement.invoice.dto.request.*;import com.procurement.invoice.dto.response.*;import com.procurement.invoice.entity.*;import com.procurement.invoice.service.*;import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/invoices")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','FINANCE_MANAGER','PROCUREMENT_MANAGER','AUDITOR')")public class InvoiceController{private final InvoiceService s;public InvoiceController(InvoiceService s){this.s=s;}@PostMapping public ResponseEntity<ApiResponse<InvoiceResponse>>create(@Valid@RequestBody InvoiceRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Invoice received",s.create(r)));}@GetMapping public ApiResponse<PageResponse<InvoiceResponse>>search(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long purchaseOrderId,@RequestParam(required=false)Long goodsReceiptNoteId,@RequestParam(required=false)InvoiceStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="id")String sort,@RequestParam(defaultValue="desc")String direction){var order="asc".equalsIgnoreCase(direction)?Sort.by(sort).ascending():Sort.by(sort).descending();var pageable=PageRequest.of(page,size,order);return ApiResponse.success(s.search(keyword,purchaseOrderId,goodsReceiptNoteId,status,pageable));}@GetMapping("/{id}")public ApiResponse<InvoiceResponse>get(@PathVariable Long id){return ApiResponse.success(s.get(id));}@PostMapping("/{id}/lines")public ResponseEntity<ApiResponse<InvoiceLineResponse>>addLine(@PathVariable Long id,@Valid@RequestBody InvoiceLineRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Invoice line added",s.addLine(id,r)));}@GetMapping("/{id}/lines")public ApiResponse<PageResponse<InvoiceLineResponse>>lines(@PathVariable Long id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(s.lines(id,PageRequest.of(page,size)));}@PostMapping("/{id}/match")public ApiResponse<InvoiceResponse>match(@PathVariable Long id){return ApiResponse.success("Invoice matched",s.match(id));}@PostMapping("/{id}/approve")public ApiResponse<InvoiceResponse>approve(@PathVariable Long id){return ApiResponse.success("Invoice approved",s.approve(id));}@PostMapping("/{id}/attachments")public ResponseEntity<ApiResponse<InvoiceAttachmentResponse>>attach(@PathVariable Long id,@RequestParam String fileName,@RequestParam String filePath,@RequestParam String fileType){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Attachment added",s.addAttachment(id,fileName,filePath,fileType)));}@GetMapping("/{id}/attachments")public ApiResponse<PageResponse<InvoiceAttachmentResponse>>attachments(@PathVariable Long id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(s.attachments(id,PageRequest.of(page,size)));}@GetMapping("/{id}/history")public ApiResponse<PageResponse<InvoiceHistoryResponse>>history(@PathVariable Long id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(s.history(id,PageRequest.of(page,size)));}}
